mapper.select:
SELECT m.*, f.value AS feedback FROM agent_message m JOIN agent_conversation c ON c.enterprise_id = m.enterprise_id AND c.id = m.conversation_id LEFT JOIN message_feedback f ON f.enterprise_id = m.enterprise_id AND f.message_id = m.id AND f.user_id = c.user_id WHERE m.enterprise_id = #{enterprise} AND m.conversation_id = #{conversation}
AND (m.created_at, CASE WHEN m.role = 'user' THEN 0 ELSE 1 END, m.id) < (#{beforeTime}, #{beforeRole}, #{beforeId})
ORDER BY m.created_at DESC, CASE WHEN m.role = 'user' THEN 0 ELSE 1 END DESC, m.id DESC LIMIT #{limit}
